M=hello;
F=main():void{
  let msg="hello world";
};

M=test;
F=main():i64{
  <42
};

M=math;
F=main():i64{
  let a=10;
  let b=20;
  let c=a+b*2;
  <c
};

M=calc;
F=main():i64{
  let x=100;
  let y=x/4;
  let z=y-5;
  <z
};

M=funcs;
F=add(a:i64;b:i64):i64{
  <a+b
};
F=main():i64{
  <add(3;4)
};

M=chain;
F=double(x:i64):i64{
  <x*2
};
F=inc(x:i64):i64{
  <x+1
};
F=main():i64{
  let v=double(inc(5));
  <v
};

M=multi;
F=square(n:i64):i64{
  <n*n
};
F=negate(n:i64):i64{
  <0-n
};
F=abs_diff(a:i64;b:i64):i64{
  if(a>b){
    <a-b
  }el{
    <b-a
  }
};
F=main():i64{
  let x=square(3);
  let y=negate(4);
  <abs_diff(x;y)
};

M=branch;
F=main():i64{
  let x=5;
  if(x>3){
    <1
  }el{
    <0
  }
};

M=grade;
F=grade(score:i64):i64{
  if(score>89){
    <4
  }el{
    if(score>79){
      <3
    }el{
      if(score>69){
        <2
      }el{
        <1
      }
    }
  }
};
F=main():i64{
  <grade(85)
};

M=loops;
F=main():i64{
  let sum=mut.0;
  lp(let i=1;i<6;i=i+1){
    sum=sum+i
  };
  <sum
};

M=arrsum;
F=sum(arr:[i64]):i64{
  let acc=mut.0;
  lp(let i=0;i<arr.len;i=i+1){
    acc=acc+arr[i]
  };
  <acc
};
F=main():i64{
  let nums=[10;20;30];
  <sum(nums)
};

M=arrays;
F=get(arr:[i64];i:i64):i64{
  <arr[i]
};
F=main():i64{
  let a=[10;20;30;40;50];
  let first=a[0];
  let last=a[4];
  <first+last
};

M=structs;
T=Point{x:i64;y:i64};
F=main():i64{
  let p=Point{x:3;y:4};
  <p.x+p.y
};

M=vec;
T=Vec2{x:i64;y:i64};
F=add(a:Vec2;b:Vec2):Vec2{
  <Vec2{x:a.x+b.x;y:a.y+b.y}
};
F=main():i64{
  let a=Vec2{x:3;y:4};
  let b=Vec2{x:10;y:20};
  let c=add(a;b);
  <c.x+c.y
};

M=strings;
I=str:std.str;
F=main():i64{
  let a="hello";
  let b=" world";
  let c=str.concat(a;b);
  let n=str.len(c);
  <n
};

M=logic;
F=both(a:bool;b:bool):bool{
  if(a){
    if(b){
      <true
    }el{
      <false
    }
  }el{
    <false
  }
};
F=main():i64{
  if(both(true;true)){
    <1
  }el{
    <0
  }
};

M=nested;
F=main():i64{
  let a=3;
  let b=7;
  let c=a*b+a-b;
  let d=c*2+a;
  let e=d-c+b*a;
  <e
};

M=deep;
F=double(x:i64):i64{<x*2};
F=inc(x:i64):i64{<x+1};
F=main():i64{
  <double(double(double(inc(inc(inc(0))))))
};

M=api.user;
I=db:std.db;
I=json:std.json;
T=User{id:i64;name:Str};
F=create(name:Str):i64{
  <1
};

M=errs;
T=FetchErr{
  NotFound:i64;
  Timeout:Str
};
F=fetch(id:i64):Str!FetchErr{
  if(id<0){
    <FetchErr.NotFound(id)
  }el{
    <"found"
  }
};
F=main():i64{
  <0
};

M=matching;
T=Shape{
  Circle:i64;
  Square:i64
};
F=area(s:Shape):i64{
  <s|{
    Circle:r r*r*3;
    Square:side side*side
  }
};
F=main():i64{
  let c=Shape.Circle(5);
  <area(c)
};

M=mutable;
F=main():i64{
  let x=mut.1;
  x=x+10;
  x=x*2;
  <x
};

M=casting;
F=main():i64{
  let narrow=42;
  let wide=narrow as i64;
  <wide
};

M=breaking;
F=find_first_gt(arr:[i64];threshold:i64):i64{
  let result=mut.0-1;
  lp(let i=0;i<arr.len;i=i+1){
    if(arr[i]>threshold){
      result=arr[i];
      br
    }el{
      result=result
    }
  };
  <result
};
F=main():i64{
  let nums=[3;7;2;9;1];
  <find_first_gt(nums;5)
};

M=returns;
F=classify(n:i64):i64{
  if(n>0){
    <1
  }el{
    if(n<0){
      <0-1
    }el{
      <0
    }
  }
};
F=main():i64{
  let a=classify(5);
  let b=classify(0-3);
  let c=classify(0);
  <a+b+c
};

M=arrop;
F=max(arr:[i64]):i64{
  let m=mut.arr[0];
  lp(let i=1;i<arr.len;i=i+1){
    if(arr[i]>m){
      m=arr[i]
    }el{
      m=m
    }
  };
  <m
};
F=main():i64{
  let data=[4;9;2;7;1;8];
  <max(data)
};

M=recurse;
F=factorial(n:i64):i64{
  if(n<2){
    <1
  }el{
    <n*factorial(n-1)
  }
};
F=main():i64{
  <factorial(5)
};

M=fib;
F=fib(n:i64):i64{
  if(n<2){
    <n
  }el{
    <fib(n-1)+fib(n-2)
  }
};
F=main():i64{
  <fib(10)
};

M=voids;
F=greet():void{
  let x=42;
};
F=main():i64{
  greet();
  <0
};

M=stats;
T=Stats{min:i64;max:i64;sum:i64};
F=compute(arr:[i64]):Stats{
  let mn=mut.arr[0];
  let mx=mut.arr[0];
  let sm=mut.arr[0];
  lp(let i=1;i<arr.len;i=i+1){
    if(arr[i]<mn){
      mn=arr[i]
    }el{
      mn=mn
    };
    if(arr[i]>mx){
      mx=arr[i]
    }el{
      mx=mx
    };
    sm=sm+arr[i]
  };
  <Stats{min:mn;max:mx;sum:sm}
};
F=main():i64{
  let data=[5;1;8;3;9;2];
  let s=compute(data);
  <s.sum
};
